// Auto-generated by scripts/generate-env.js from .env / environment variables.
declare global {
  interface Window {
    __ENV__?: Record<string, string>;
  }
}

const runtimeEnv = typeof window !== 'undefined' ? window.__ENV__ : undefined;

export const environment = {
  production: (runtimeEnv?.['APP_ENV'] ?? "development") === 'production',
  appEnv: runtimeEnv?.['APP_ENV'] ?? "development",
  apiBaseUrl: runtimeEnv?.['API_BASE_URL'] ?? "/api/v1",
  apiProxyTarget: runtimeEnv?.['API_PROXY_TARGET'] ?? "http://localhost:5000",
  patientPortalUrl: runtimeEnv?.['PATIENT_PORTAL_URL'] ?? "http://localhost:4300",
  defaultSourceId: runtimeEnv?.['DEFAULT_SOURCE_ID'] ?? "f0000000-0000-4000-8000-000000000001",
  branchUtcOffsetHours: Number(runtimeEnv?.['BRANCH_UTC_OFFSET'] ?? "-5"),
};
